def _convertir(bloques):
    """«Título» con nivel → bloques «Subtítulo» (H2) y «Subtítulo menor» (H3/H4). El texto no cambia."""
    cambio = False
    for b in bloques or []:
        if b.get("type") == "titulo":
            v = b.get("value") or {}
            b["type"] = "h2" if v.get("nivel") == "h2" else "h3"
            b["value"] = v.get("texto", "")
            cambio = True
    return cambio


def titulos_a_subtitulos(apps, schema_editor):
    import json
    Articulo = apps.get_model("contenidos", "ArticuloPage")
    Revision = apps.get_model("wagtailcore", "Revision")
    ContentType = apps.get_model("contenttypes", "ContentType")
    for a in Articulo.objects.all():
        datos = a.cuerpo.raw_data if hasattr(a.cuerpo, "raw_data") else a.cuerpo
        datos = list(datos)
        if _convertir(datos):
            Articulo.objects.filter(pk=a.pk).update(cuerpo=json.dumps(datos))
    ct = ContentType.objects.filter(app_label="contenidos", model="articulopage").first()
    if ct is None:
        return
    for r in Revision.objects.filter(content_type=ct):
        contenido = r.content
        cuerpo = contenido.get("cuerpo")
        if isinstance(cuerpo, str):
            cuerpo = json.loads(cuerpo)
        if _convertir(cuerpo):
            contenido["cuerpo"] = json.dumps(cuerpo)
            r.content = contenido
            r.save(update_fields=["content"])


